import{_ as e,o as a,c as n,a9 as r}from"./chunks/framework.asyjyako.js";const m=JSON.parse('{"title":"Contribute an experiment","description":"","frontmatter":{},"headers":[],"relativePath":"real-packages/contributing.md","filePath":"real-packages/contributing.md","lastUpdated":null}'),o={name:"real-packages/contributing.md"};function i(s,t,d,l,c,p){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="Contribute-an-experiment" tabindex="-1">Contribute an experiment <a class="header-anchor" href="#Contribute-an-experiment" aria-label="Permalink to &quot;Contribute an experiment {#Contribute-an-experiment}&quot;">​</a></h1><p>To contribute an example, open a pull request with the workload code, its measurements and plots. You can add a package, an operation or an improvement to an existing example. Include enough information for another maintainer to repeat the comparison.</p><p>Start from <code>examples/kitchen-sink</code>. Keep the lifecycle small: prepare the input, perform one meaningful operation, verify the answer independently. Existing TestItems are welcome. Add explicit tags only when an item must be restricted to correctness or performance runs.</p><p>Include these facts with the result:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Evidence</th><th style="text-align:right;">Why it matters</th></tr></thead><tbody><tr><td style="text-align:right;">Package versions or immutable revisions, dependency manifests</td><td style="text-align:right;">Reconstruct the compared implementations</td></tr><tr><td style="text-align:right;">Workload and fixture source, seed or frozen corpus</td><td style="text-align:right;">Repeat the same work</td></tr><tr><td style="text-align:right;">Oracle and its outcome</td><td style="text-align:right;">Reject fast but incorrect answers</td></tr><tr><td style="text-align:right;">Julia version, machine, operating system, threads and CPU allocation</td><td style="text-align:right;">Understand the execution conditions</td></tr><tr><td style="text-align:right;">Collector, sample count, units and preparation boundary</td><td style="text-align:right;">Know what the numbers measure</td></tr><tr><td style="text-align:right;">Raw observations or a downloadable bundle</td><td style="text-align:right;">Replot and inspect variation</td></tr><tr><td style="text-align:right;">Baseline, change and repeated confirmation</td><td style="text-align:right;">Separate an improvement from noise</td></tr></tbody></table><p>Generate the plots from saved measurements so documentation builds stay fast. Attach large bundles and recordings to a release or another durable download location. Include notebooks as <code>.jl</code> files that readers can edit and run.</p><p>List unsuccessful checks with their errors, and identify tools or platforms you could not test.</p><p>For an optimization, explain the code change and compare the repeated measurements before and after it. Include the correctness-check result and machine settings so others can try the change on their own systems.</p>',8)])])}const u=e(o,[["render",i]]);export{m as __pageData,u as default};
